    int bl_count[HUFF_MAX_CODE_LEN + 2];
    #pragma unroll
    for (int i = 0; i <= HUFF_MAX_CODE_LEN + 1; ++i) bl_count[i] = 0;
    for (int s = 0; s < HUFF_ALPHABET_SIZE; ++s) {
