        first_code[l] = 0;
        first_idx[l]  = 0;
    }
    {
        uint32_t code = 0;
        int      idx  = 0;
        for (int l = 1; l <= HUFF_MAX_CODE_LEN; ++l) {
            code = (code + (uint32_t)bl_count[l - 1]) << 1;
            first_code[l] = code;
            first_idx[l]  = idx;
            idx += bl_count[l];
        }
    }

    // Build LUT for fast decoding
    LUTEntry lut[1 << LUT_BITS];
    #pragma unroll 4
    for (int i = 0; i < (1 << LUT_BITS); ++i) {
        lut[i].symbol = 0xFFFF;
        lut[i].length = 0;
    }

    // Populate LUT by iterating through all symbols
    for (int sym_idx = 0; sym_idx < HUFF_ALPHABET_SIZE; ++sym_idx) {
        uint16_t sym = symbols_g[sym_idx];
        uint8_t len = code_len_g[sym];
        if (len == 0 || len > HUFF_MAX_CODE_LEN) continue;

        // Find the code for this symbol
        uint32_t code = first_code[len] + (sym_idx - first_idx[len]);

        // Fill all LUT entries that start with this code
        if (len <= LUT_BITS) {
            uint32_t prefix = code << (LUT_BITS - len);
            uint32_t count = 1u << (LUT_BITS - len);
            for (uint32_t j = 0; j < count; ++j) {
                lut[prefix + j].symbol = sym;
                lut[prefix + j].length = len;
            }
        } else {
            // Code longer than LUT - store in first matching entry
            uint32_t prefix = code >> (len - LUT_BITS);
            if (lut[prefix].length == 0) {
                lut[prefix].symbol = sym;
                lut[prefix].length = len;
            }
        }
    }

    const uint32_t* my_bits = bits_buf + (size_t)k * bits_stride;
    uint32_t        bit_len = bit_lens[k];
    uint8_t*        my_out  = out_buf  + (size_t)k * out_stride;
    uint32_t        out_len = out_lens[k];

    uint32_t pos = 0;
    uint32_t buffer = 0;
    int buffer_bits = 0;

    for (uint32_t i = 0; i < out_len; ++i) {
        // Fill buffer with enough bits
        while (buffer_bits < LUT_BITS && pos < bit_len) {
            uint32_t word_idx = pos >> 5;
            uint32_t bit_in_word = pos & 31u;
            uint32_t available = 32 - bit_in_word;
            uint32_t bits_to_read = (bit_len - pos < available) ? (bit_len - pos) : available;

            uint32_t w = my_bits[word_idx];
            uint32_t bits = (w >> bit_in_word) & ((1u << bits_to_read) - 1);
            buffer |= bits << buffer_bits;
            buffer_bits += bits_to_read;
            pos += bits_to_read;
        }

        // Look up in LUT
        uint32_t lut_idx = buffer & ((1u << LUT_BITS) - 1);
        LUTEntry entry = lut[lut_idx];

        if (entry.length > 0 && entry.length <= buffer_bits) {
            my_out[i] = (uint8_t)entry.symbol;
            buffer >>= entry.length;
            buffer_bits -= entry.length;
        } else {
            // Fallback: bit-by-bit decode
            uint32_t cur = 0;
            int l = 0;
            bool done = false;
            while (l < HUFF_MAX_CODE_LEN && l < buffer_bits) {
                uint32_t b = (buffer >> l) & 1u;
                cur = (cur << 1) | b;
                l++;
                if (bl_count[l] > 0 &&
                    cur < first_code[l] + (uint32_t)bl_count[l]) {
                    int o = first_idx[l] + (int)(cur - first_code[l]);
                    my_out[i] = (uint8_t)symbols_g[o];
                    buffer >>= l;
                    buffer_bits -= l;
                    done = true;
                    break;
                }
            }
            if (!done) {
                my_out[i] = 0xFF;
                return;
            }
        }
    }
}

